#[derive(Deserialize)]
struct RawTransaction {
    #[serde(rename = "type")]
    tx_type: String,
    client: u16,
    tx: u32,
    amount: Option<Decimal>,
}

impl<'de> Deserialize<'de> for Transaction {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let raw = RawTransaction::deserialize(deserializer)?;
        match raw.tx_type.as_str() {
            "deposit" => {
                let amount = raw
                    .amount
                    .ok_or_else(|| DeError::custom("deposit record is missing amount"))?;
                Ok(Transaction::Deposit {
                    client: raw.client,
                    tx: raw.tx,
                    amount,
                })
            }
            "withdraw" => {
                let amount = raw
                    .amount
                    .ok_or_else(|| DeError::custom("withdraw record is missing amount"))?;
                Ok(Transaction::Withdraw {
                    client: raw.client,
                    tx: raw.tx,
                    amount,
                })
            }
            "dispute" => Ok(Transaction::Dispute {
                client: raw.client,
                tx: raw.tx,
            }),
            "resolve" => Ok(Transaction::Resolve {
                client: raw.client,
                tx: raw.tx,
            }),
            "chargeback" => Ok(Transaction::Chargeback {
                client: raw.client,
                tx: raw.tx,
            }),
            other => Err(DeError::custom(format!(
                "unknown transaction type: {other}"
            ))),
        }
    }
}

